===== BK7258 hwspinlock 实现 =====
/****************************************************************************
 * BK7258 AP_SPINLOCK-backed software hwspinlock.
 ****************************************************************************/

#include <nuttx/config.h>

#include <assert.h>
#include <stdbool.h>
#include <stdint.h>

#include <nuttx/hwspinlock/hwspinlock.h>

#include "arm_internal.h"

static volatile uint32_t g_bk7258_atomic_gate
  __attribute__((section(".bk_spinlock"), aligned(32)));

static bool bk7258_hwspinlock_trylock(struct hwspinlock_dev_s *dev)
{
  uint32_t owner = (uint32_t)up_cpu_index() + 1u;
  uint32_t value;
  uint32_t status;

  (void)dev;
  __asm__ volatile
    (
      "ldaex %0, [%2]\n"
      "cmp %0, #0\n"
      "bne 1f\n"
      "strex %1, %3, [%2]\n"
      "b 2f\n"
      "1: clrex\n"
      "mov %1, #1\n"
      "2:\n"
      : "=&r"(value), "=&r"(status)
      : "r"(&g_bk7258_atomic_gate), "r"(owner)
      : "cc", "memory"
    );

  return value == 0 && status == 0;
}

static void bk7258_hwspinlock_relax(struct hwspinlock_dev_s *dev)
{
  (void)dev;
  __asm__ volatile("wfe" ::: "memory");
}

static void bk7258_hwspinlock_unlock(struct hwspinlock_dev_s *dev)
{
  uint32_t owner = (uint32_t)up_cpu_index() + 1u;
  uint32_t unlocked = 0;

  (void)dev;
  if (g_bk7258_atomic_gate != owner)
    {
      PANIC();
    }

  __asm__ volatile("stl %1, [%0]\n"
                   "dsb sy\n"
                   "sev\n"
                   :
                   : "r"(&g_bk7258_atomic_gate), "r"(unlocked)
                   : "memory");
}

const struct hwspinlock_ops_s g_bk7258_hwspinlock_ops =
{
  .trylock = bk7258_hwspinlock_trylock,
  .relax   = bk7258_hwspinlock_relax,
  .unlock  = bk7258_hwspinlock_unlock
};

void bk7258_hwspinlock_initialize(void)
{
  g_bk7258_atomic_gate = 0;
  UP_DSB();
  __asm__ volatile("sev" ::: "memory");
}

